const token = $env.GITHUB_TOKEN;
const headers = {
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'bizos-n8n-github-poll',
};
if (token) {
  headers.Authorization = `Bearer ${token}`;
}

const url = new URL('https://api.github.com/repos/pmwasim/bizOS/actions/runs');
url.searchParams.set('status', 'completed');
url.searchParams.set('per_page', '10');

const response = await fetch(url, { headers });
if (!response.ok) {
  throw new Error(`GitHub API ${response.status}: ${await response.text()}`);
}

return [{ json: await response.json() }];

const runs = $input.first().json.workflow_runs ?? [];
const staticData = $getWorkflowStaticData('global');
if (!staticData.notifiedRunIds) {
  staticData.notifiedRunIds = {};
}

const failures = runs.filter((run) => {
  if (run.conclusion !== 'failure' && run.conclusion !== 'cancelled') {
    return false;
  }
  if (staticData.notifiedRunIds[String(run.id)]) {
    return false;
  }
  return true;
});

return failures.map((run) => ({
  json: {
    event: 'ci.failure',
    source: 'github-actions-poll',
    idempotencyKey: `gh-run-${run.id}`,
    repo: 'pmwasim/bizOS',
    workflow: run.name,
    runId: run.id,
    runUrl: run.html_url,
    branch: run.head_branch,
    sha: run.head_sha?.slice(0, 7),
    conclusion: run.conclusion,
    actor: run.actor?.login ?? 'unknown',
    createdAt: run.created_at,
  },
}));

const staticData = $getWorkflowStaticData('global');
if (!staticData.notifiedRunIds) {
  staticData.notifiedRunIds = {};
}
staticData.notifiedRunIds[String($json.runId)] = $now.toISO();

// Keep map bounded
const keys = Object.keys(staticData.notifiedRunIds);
if (keys.length > 200) {
  for (const key of keys.slice(0, keys.length - 200)) {
    delete staticData.notifiedRunIds[key];
  }
}

return [{ json: { ...$json, status: 'routed' } }];

const item = $input.first().json;
const mailpit = $env.BIZOS_OPS_MAILPIT_URL;
const webhook = $env.BIZOS_OPS_ALERT_WEBHOOK_URL;
const to = $env.BIZOS_OPS_ALERT_EMAIL || 'ops@bizos.local';
const from = $env.BIZOS_OPS_ALERT_FROM || 'n8n@bizos.local';
const title = item.title || '[bizOS] GitHub failure';
const message = item.message || JSON.stringify(item);

async function deliver() {
  if (mailpit) {
    const url = String(mailpit).replace(/\/$/, '') + '/api/v1/send';
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        From: { Email: from, Name: 'bizOS n8n' },
        To: [{ Email: to }],
        Subject: title,
        Text: message,
      }),
    });
    if (!response.ok) {
      throw new Error('Mailpit send failed: ' + response.status + ' ' + (await response.text()));
    }
    return { deliveredVia: 'mailpit', status: 'delivered' };
  }
  if (webhook) {
    const response = await fetch(webhook, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...item, title, message }),
    });
    if (!response.ok) {
      throw new Error('Alert webhook failed: ' + response.status);
    }
    return { deliveredVia: 'webhook', status: 'delivered' };
  }
  return { deliveredVia: 'log', status: 'logged' };
}

const result = await deliver();
return [{ json: { ...item, ...result, deliveredAt: new Date().toISOString() } }];
